SELECT zone_id, ST_GeometryType(polygon) AS gtype, ST_NumGeometries(polygon) AS parts,
       ROUND((ABS(ST_Area(polygon::geography))/1e6)::numeric,4) AS km2,
       ST_IsValid(polygon) AS valid, effective_from, effective_to
FROM enterprise.nl_compliance_zones
WHERE zone_id IN ('utrecht_ze_zone_2025','eindhoven_ze_zone_2025') ORDER BY zone_id;

\echo ''
\echo '=== Sanity (8 Utrecht + 8 Eindhoven) ==='
WITH p AS (
  SELECT 'U_Domtoren_IN' AS loc,'utrecht_ze_zone_2025' AS zid,5.1214 AS lon,52.0907 AS lat,'inside' AS exp UNION ALL
  SELECT 'U_Neude_IN','utrecht_ze_zone_2025',5.1190,52.0925,'inside' UNION ALL
  SELECT 'U_Vredenburg_IN','utrecht_ze_zone_2025',5.1148,52.0925,'inside' UNION ALL
  SELECT 'U_HoogCatharijne_IN','utrecht_ze_zone_2025',5.1100,52.0892,'inside' UNION ALL
  SELECT 'U_Lombok_OUT','utrecht_ze_zone_2025',5.0950,52.0880,'outside' UNION ALL
  SELECT 'U_Wittevrouwen_OUT','utrecht_ze_zone_2025',5.1330,52.0960,'outside' UNION ALL
  SELECT 'U_Lunetten_OUT','utrecht_ze_zone_2025',5.1230,52.0640,'outside' UNION ALL
  SELECT 'U_Overvecht_OUT','utrecht_ze_zone_2025',5.1080,52.1180,'outside' UNION ALL
  SELECT 'E_Markt_IN','eindhoven_ze_zone_2025',5.4790,51.4400,'inside' UNION ALL
  SELECT 'E_Stadhuisplein_IN','eindhoven_ze_zone_2025',5.4770,51.4380,'inside' UNION ALL
  SELECT 'E_CS_IN','eindhoven_ze_zone_2025',5.4815,51.4430,'inside' UNION ALL
  SELECT 'E_18Sept_IN','eindhoven_ze_zone_2025',5.4785,51.4415,'inside' UNION ALL
  SELECT 'E_StrijpS_OUT','eindhoven_ze_zone_2025',5.4520,51.4480,'outside' UNION ALL
  SELECT 'E_Woensel_OUT','eindhoven_ze_zone_2025',5.4800,51.4700,'outside' UNION ALL
  SELECT 'E_Stratum_OUT','eindhoven_ze_zone_2025',5.4900,51.4200,'outside' UNION ALL
  SELECT 'E_Gestel_OUT','eindhoven_ze_zone_2025',5.4500,51.4250,'outside'
)
SELECT loc, exp,
  CASE WHEN ST_Contains((SELECT polygon FROM enterprise.nl_compliance_zones WHERE zone_id=p.zid), ST_SetSRID(ST_MakePoint(lon,lat),4326))
       THEN 'inside' ELSE 'outside' END AS act,
  CASE WHEN exp = CASE WHEN ST_Contains((SELECT polygon FROM enterprise.nl_compliance_zones WHERE zone_id=p.zid), ST_SetSRID(ST_MakePoint(lon,lat),4326)) THEN 'inside' ELSE 'outside' END
       THEN 'PASS' ELSE 'FAIL' END AS result
FROM p ORDER BY zid, exp DESC, loc;

